// DANGER: Infinite Loop (Unsigned type 'i' is always >= 0)
size_t N = 10;
for (size_t i = N; i >= 0; --i) {
    // 0 underflows to SIZE_MAX
}

// SAFE FIX 1: Adjust Condition (Iterates N down to 1)
for (size_t i = N; i > 0; --i) { /* OK */ }

// SAFE FIX 2: Use Signed Type (Standard iteration 9 down to 0)
for (long long i = N - 1; i >= 0; --i) { /* OK */ }

// SAFE FIX 3: Use while loop structure
size_t i = N;
while (i-- > 0) {
    // Uses i before decrement (N down to 1)
}
